<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{api,session}from'../api';const accounts=ref<any[]>([]),rooms=ref<any[]>([]),tab=ref('accounts'),show=ref(false),canEdit=session.permissions.includes('accounts.manage'),account=reactive({name:'',platform:'TikTok',owner_name:'',target_region_id:'us-los-angeles',room_id:null as number|null,notes:'',status:'active'}),room=reactive({name:'',region:'',bitrate_kbps:6000,notes:'',status:'active'});async function load(){const [a,r]=await Promise.all([api('/tk-api/enterprise/accounts'),api('/tk-api/enterprise/rooms')]);accounts.value=a.accounts;rooms.value=r.rooms;}async function save(){if(tab.value==='accounts')await api('/tk-api/enterprise/accounts',{method:'POST',body:JSON.stringify(account)});else await api('/tk-api/enterprise/rooms',{method:'POST',body:JSON.stringify(room)});show.value=false;load();}onMounted(load);</script>
<template><section class="panel"><header class="panel-head"><div><span class="eyebrow">LIVE OPERATIONS STRUCTURE</span><h2>直播间与开播账号</h2><p>只保存企业内部识别信息，不保存平台密码、Cookie和登录状态。</p></div><button v-if="canEdit" class="primary" @click="show=!show">新增{{tab==='accounts'?'开播账号':'直播间'}}</button></header><div class="segmented"><button :class="{active:tab==='accounts'}" @click="tab='accounts'">开播账号</button><button :class="{active:tab==='rooms'}" @click="tab='rooms'">直播间</button></div><form v-if="show" class="inline-form" @submit.prevent="save"><template v-if="tab==='accounts'"><input v-model="account.name" placeholder="账号内部名称" required><input v-model="account.owner_name" placeholder="负责人"><select v-model="account.room_id"><option :value="null">暂不关联直播间</option><option v-for="x in rooms" :value="x.id">{{x.name}}</option></select><input v-model="account.target_region_id" placeholder="目标地区"></template><template v-else><input v-model="room.name" placeholder="直播间名称" required><input v-model="room.region" placeholder="地区"><input v-model.number="room.bitrate_kbps" type="number" placeholder="参考码率"><input v-model="room.notes" placeholder="备注"></template><button class="primary">保存</button></form><div class="entity-grid" v-if="tab==='accounts'"><article v-for="x in accounts"><span class="entity-icon">T</span><div><b>{{x.name}}</b><p>{{x.platform}} · {{x.owner_name||'未设置负责人'}}</p></div><span class="role-badge">{{x.target_region_id}}</span></article></div><div class="entity-grid" v-else><article v-for="x in rooms"><span class="entity-icon">⌂</span><div><b>{{x.name}}</b><p>{{x.region||'未设置地区'}} · {{x.bitrate_kbps}} Kbps</p></div><span class="role-badge">{{x.status}}</span></article></div></section></template>
